// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    address[2] callers;

    function setUp() public {
        c = new ModifierEntrancy();
        callers[0] = address(new BankCaller());
        callers[1] = address(new BankCaller());
    }

    function testFuzz_property(uint256 idx) public {
        uint256 i = bound(idx, 0, 1);
        address actor = callers[i];
        vm.assume(c.tokenBalance(actor) == 0);
        vm.prank(actor);
        try c.airDrop() {
            assertTrue(c.tokenBalance(actor) == 20, "zero-balance bank caller must be airdropped 20");
        } catch {
            assertTrue(false, "airDrop must succeed for any zero-balance bank caller");
        }
    }
}

contract BankCaller {
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
}
